installer-gui-script.script:
function checkArch() {
    var arm = system.sysctl("hw.optional.arm64") == 1;
    if ("@ARCH@" == "x86_64" && arm) {
        // works (through Rosetta), but the Apple silicon version is faster: recommend it, allow continuing
        my.result.title = "There is a faster VeilMark for this Mac";
        my.result.message = "This Mac has an Apple chip. The installer for Apple silicon runs faster. You can still continue with this Intel version.";
        my.result.type = "Warning";
        return false;
    }
    if ("@ARCH@" == "arm64" && !arm) {
        my.result.title = "This installer is for Apple silicon Macs";
        my.result.message = "This Mac has an Intel processor. Please download the VeilMark installer for Intel Macs instead.";
        my.result.type = "Fatal";
        return false;
    }
    return true;
}
